import { cn } from "@/shared/lib/utils";

type IconSize = "xs" | "sm" | "md" | "lg" | "xl";

interface IconProps extends React.SVGProps<SVGSVGElement> {
  className?: string;
  size?: IconSize | number;
}

interface SidebarToggleProps extends IconProps {
  isCollapsed?: boolean;
}

// Size mapping
const SIZE_MAP: Record<IconSize, number> = {
  xs: 16,
  sm: 20,
  md: 24,
  lg: 28,
  xl: 32,
};

// Helper function to get size value
const getSize = (size?: IconSize | number): number => {
  if (typeof size === "number") return size;
  if (size && size in SIZE_MAP) return SIZE_MAP[size];
  return SIZE_MAP.md; // default
};

// Base icon wrapper component
const createIcon = (
  paths: (size: number) => JSX.Element,
  displayName: string,
  defaultViewBox: string = "0 0 24 24"
) => {
  const Icon = ({ className, size, ...props }: IconProps) => {
    const iconSize = getSize(size);

    return (
      <svg
        xmlns="http://www.w3.org/2000/svg"
        width={iconSize}
        height={iconSize}
        viewBox={defaultViewBox}
        fill="none"
        className={cn("shrink-0", className)}
        aria-hidden="true"
        {...props}
      >
        {paths(iconSize)}
      </svg>
    );
  };

  Icon.displayName = displayName;
  return Icon;
};

